def endpoint_prefix(cutoff):
    """Return ``cutoff`` endpoint symbols from {1,2}, with no adjacent 1s."""
    result = []
    for i in range(cutoff):
        if i == 0:
            result.append(1)  # Start with 1
        elif result[-1] == 1:
            result.append(2)  # Always follow 1 with 2
        else:
            result.append(1)  # Follow 2 with 1
    return tuple(result)
